/**
 * Role-based access control (RBAC) for God's Eye View API endpoints.
 *
 * Roles (least → most privilege):
 *   viewer   – read-only access to public feeds (ADS-B, vessels, satellites,
 *              earthquakes, fires, CCTV public streams).
 *   operator – everything viewer can do, plus cost-bearing proxies (Google
 *              Places, OpenSky authenticated, terrain heights) and exercise mode.
 *   admin    – full access including configuration endpoints and audit logs.
 *
 * Default: DENY. Every /api route must match an entry in ROUTE_POLICY or the
 * request is rejected with 403 before reaching the provider.
 *
 * @module server/auth/authorize
 */

/** All recognised roles, in ascending privilege order. */
export const ROLES = Object.freeze(['viewer', 'operator', 'admin']);

/**
 * Minimum role required to access each /api path prefix.
 * Longer prefixes take priority over shorter ones (most-specific match).
 *
 * 'public' means the route is accessible without authentication (only for
 * routes that genuinely need to be reachable before sign-in, e.g. /api/health).
 */
export const ROUTE_POLICY = Object.freeze([
  // ── unauthenticated ───────────────────────────────────────────────────────
  { prefix: '/api/health', role: 'public' },

  // ── viewer ────────────────────────────────────────────────────────────────
  { prefix: '/api/opensky', role: 'viewer' },
  { prefix: '/api/adsblol', role: 'viewer' },
  { prefix: '/api/celestrak', role: 'viewer' },
  { prefix: '/api/firms', role: 'viewer' },
  { prefix: '/api/overpass', role: 'viewer' },
  { prefix: '/api/military-installations', role: 'viewer' },
  { prefix: '/api/cyclones', role: 'viewer' },
  { prefix: '/api/metar', role: 'viewer' },
  { prefix: '/api/cctv', role: 'viewer' },
  { prefix: '/api/ais-live', role: 'viewer' },
  { prefix: '/api/space', role: 'viewer' },

  // ── operator ──────────────────────────────────────────────────────────────
  { prefix: '/api/terrain', role: 'operator' },
  { prefix: '/api/places', role: 'operator' },
  { prefix: '/api/enrich', role: 'operator' },
  { prefix: '/api/tracks', role: 'operator' },
  { prefix: '/api/geocode', role: 'operator' },

  // ── admin ─────────────────────────────────────────────────────────────────
  { prefix: '/api/admin', role: 'admin' },
]);

/**
 * Resolve the minimum required role for a request path.
 * Returns 'deny' when no policy matches (default-deny).
 * @param {string} path
 * @returns {'public'|'viewer'|'operator'|'admin'|'deny'}
 */
export function requiredRole(path) {
  // Sort by descending prefix length so the most-specific rule wins.
  const sorted = [...ROUTE_POLICY].sort(
    (a, b) => b.prefix.length - a.prefix.length,
  );
  for (const entry of sorted) {
    if (path === entry.prefix || path.startsWith(entry.prefix + '/') ||
        path.startsWith(entry.prefix + '?')) {
      return entry.role;
    }
  }
  return 'deny';
}

/**
 * Return true when `userRole` satisfies `required`.
 * @param {string} userRole
 * @param {'public'|'viewer'|'operator'|'admin'|'deny'} required
 */
export function hasPermission(userRole, required) {
  if (required === 'public') return true;
  if (required === 'deny') return false;
  const userIdx = ROLES.indexOf(userRole);
  const reqIdx = ROLES.indexOf(required);
  return userIdx >= 0 && reqIdx >= 0 && userIdx >= reqIdx;
}

/**
 * Connect middleware: enforce RBAC on every /api request.
 * Must be installed after the auth session middleware (which attaches
 * req.gevSession).
 *
 * @param {import('http').IncomingMessage & { gevSession?: object }} req
 * @param {import('http').ServerResponse} res
 * @param {() => void} next
 */
export function authorizeMiddleware(req, res, next) {
  const url = req.url ?? '';
  if (!url.startsWith('/api/')) return next();

  const path = url.split('?')[0];
  const required = requiredRole(path);

  if (required === 'public') return next();

  const session = req.gevSession;
  if (!session) {
    return sendJson(res, 401, { error: 'Authentication required' });
  }

  if (!session.mfaVerified) {
    return sendJson(res, 401, { error: 'MFA verification required' });
  }

  if (!hasPermission(session.roles?.[0], required)) {
    return sendJson(res, 403, {
      error: 'Forbidden',
      required,
      userRoles: session.roles,
    });
  }

  next();
}

function sendJson(res, status, body) {
  const payload = JSON.stringify(body);
  res.writeHead(status, {
    'Content-Type': 'application/json',
    'Cache-Control': 'no-store',
  });
  res.end(payload);
}

/**
 * Authentication middleware for God's Eye View.
 *
 * Implements a lightweight OIDC-inspired session gate:
 *
 *   1. Every request checks for a valid, MFA-verified session cookie.
 *   2. Unauthenticated requests to HTML pages get a redirect to /auth/login.
 *   3. Unauthenticated /api requests get 401 JSON.
 *   4. POST /auth/login validates credentials, issues a partial session, then
 *      redirects to POST /auth/totp for the second factor.
 *   5. POST /auth/totp verifies the TOTP code and marks the session MFA-verified.
 *   6. POST /auth/logout destroys the session and clears the cookie.
 *   7. GET  /auth/totp-setup   returns the TOTP URI and secret for enrolment
