 */
import { createHash } from 'node:crypto';
import {
  createSession,
  resolveSession,
  markMfaVerified,
  destroySession,
  buildSetCookie,
  buildClearCookie,
} from './session.js';
import { verifyTotp, generateTotpSecret, totpUri } from './totp.js';
import { authorizeMiddleware } from './authorize.js';

const IS_PROD = process.env.NODE_ENV === 'production';
const AUTH_DISABLED =
  process.env.GEV_AUTH_DISABLED === '1' && !IS_PROD;

// ── built-in credential store (dev / demo; replace with IdP in production) ──

const ADMIN_USER = process.env.GEV_ADMIN_USER || 'admin';

/** sha256 hex hash of the admin password. */
const ADMIN_PASS_HASH = (() => {
  const env = process.env.GEV_ADMIN_PASS_HASH;
  if (env) return env.toLowerCase();
  if (IS_PROD)
    throw new Error('GEV_ADMIN_PASS_HASH must be set in production.');
  // Dev default – password: "changeme" (sha256)
  return createHash('sha256').update('changeme').digest('hex');
})();

/** Base32 TOTP secret for the admin account. */
const ADMIN_TOTP = (() => {
  const env = process.env.GEV_ADMIN_TOTP;
  if (env) return env;
  if (IS_PROD)
    throw new Error('GEV_ADMIN_TOTP must be set in production.');
  // Dev default – generated once at startup (printed to console).
  const secret = generateTotpSecret();
  console.warn(
    `[auth] Dev TOTP secret (scan with your authenticator): ${secret}\n` +
    `[auth] TOTP URI: ${totpUri(secret, "God's Eye View", ADMIN_USER)}`,
  );
  return secret;
})();

/**
 * Validate username + password. In production this delegates to the IdP token
 * endpoint. Here we check the built-in credential store.
 * @param {string} username
 * @param {string} password
 * @returns {{ userId: string, roles: string[] } | null}
 */
function validateCredentials(username, password) {
  if (username !== ADMIN_USER) return null;
  const hash = createHash('sha256').update(password).digest('hex');
  if (hash !== ADMIN_PASS_HASH) return null;
  return { userId: username, roles: ['admin'] };
}

