      <button type="submit">Verify</button>
    </form>
  </div>
</body>
</html>`;

// ── request body parser (URL-encoded forms only) ─────────────────────────────

function parseFormBody(req) {
  return new Promise((resolve, reject) => {
    let body = '';
    req.on('data', (chunk) => {
      body += chunk;
      if (body.length > 4096) {
        reject(new Error('Request body too large'));
        req.destroy();
      }
    });
    req.on('end', () => {
      const params = new URLSearchParams(body);
      resolve(Object.fromEntries(params));
    });
    req.on('error', reject);
  });
}

// ── middleware ───────────────────────────────────────────────────────────────

/**
 * Core authentication middleware.
 * Attaches req.gevSession when a valid, MFA-verified session exists.
 */
export function authMiddleware(req, res, next) {
  if (AUTH_DISABLED) {
    req.gevSession = {
      userId: 'dev',
      roles: ['admin'],
      mfaVerified: true,
      token: 'dev',
    };
    return next();
  }

  const session = resolveSession(req);
  if (session) req.gevSession = session;

  const url = req.url ?? '';
  const path = url.split('?')[0];
  const method = (req.method ?? 'GET').toUpperCase();

  // Auth endpoints are always accessible.
  if (path.startsWith('/auth/')) {
    return handleAuthRoute(path, method, req, res, next);
  }

  next();
}

/** Handle /auth/* routes (login, totp, logout, setup). */
function handleAuthRoute(path, method, req, res, next) {
  // GET /auth/login → login page
  if (path === '/auth/login' && method === 'GET') {
    return sendHtml(res, 200, LOGIN_HTML.replace('{{ERROR}}', ''));
  }

  // POST /auth/login → validate credentials, set partial session, redirect to MFA
  if (path === '/auth/login' && method === 'POST') {
    return parseFormBody(req)
      .then((body) => {
        const user = validateCredentials(
          String(body.username ?? '').trim(),
          String(body.password ?? ''),
        );
        if (!user) {
          return sendHtml(
            res,
            401,
            LOGIN_HTML.replace(
              '{{ERROR}}',
              '<p class="error">Invalid username or password.</p>',
            ),
          );
        }
        // Create a partial session (mfaVerified = false) pending TOTP step.
        const { cookieValue, expiresAt } = createSession({
          userId: user.userId,
          roles: user.roles,
          mfaVerified: false,
        });
        res.writeHead(302, {
          'Set-Cookie': buildSetCookie(cookieValue, expiresAt),
          Location: '/auth/totp',
          'Cache-Control': 'no-store',
        });
        res.end();
      })
      .catch(() => sendHtml(res, 400, LOGIN_HTML.replace('{{ERROR}}', '')));
  }

  // GET /auth/totp → TOTP verification page (requires partial session)
  if (path === '/auth/totp' && method === 'GET') {
    return sendHtml(res, 200, TOTP_HTML.replace('{{ERROR}}', ''));
  }

  // POST /auth/totp → verify TOTP code, mark session MFA-verified
  if (path === '/auth/totp' && method === 'POST') {
    const session = req.gevSession;
    if (!session) {
      res.writeHead(302, { Location: '/auth/login', 'Cache-Control': 'no-store' });
      return res.end();
    }
    return parseFormBody(req)
      .then((body) => {
        const code = String(body.code ?? '').trim();
        if (!verifyTotp(ADMIN_TOTP, code)) {
          return sendHtml(
            res,
            401,
            TOTP_HTML.replace(
              '{{ERROR}}',
              '<p class="error">Invalid code. Please try again.</p>',
            ),
          );
        }
        markMfaVerified(session.token);
        res.writeHead(302, { Location: '/', 'Cache-Control': 'no-store' });
        res.end();
      })
      .catch(() => sendHtml(res, 400, TOTP_HTML.replace('{{ERROR}}', '')));
  }

  // POST /auth/logout → destroy session, redirect to login
  if (path === '/auth/logout' && method === 'POST') {
    const session = req.gevSession;
    if (session) destroySession(session.token);
    res.writeHead(302, {
      'Set-Cookie': buildClearCookie(),
      Location: '/auth/login',
      'Cache-Control': 'no-store',
    });
    return res.end();
  }

  // Anything else under /auth → 404
  res.writeHead(404, { 'Content-Type': 'text/plain' });
  res.end('Not found');
}

/**
 * Redirect unauthenticated requests that are not API calls.
 * Must be installed after authMiddleware and authorizeMiddleware.
 */
export function requireAuthMiddleware(req, res, next) {
  if (AUTH_DISABLED) return next();

  const url = req.url ?? '';
  const path = url.split('?')[0];

  // Auth routes and public assets are exempt.
  if (
    path.startsWith('/auth/') ||
    path.startsWith('/brand/') ||
    path === '/favicon.ico' ||
    path === '/style.css'
  )
    return next();

  const session = req.gevSession;

  // Not authenticated → redirect to login (HTML) or 401 (API).
  if (!session) {
    if (path.startsWith('/api/')) {
      res.writeHead(401, {
        'Content-Type': 'application/json',
        'Cache-Control': 'no-store',
        'WWW-Authenticate': 'Session realm="God\'s Eye View"',
      });
      return res.end(JSON.stringify({ error: 'Authentication required' }));
    }
    res.writeHead(302, {
      Location: '/auth/login',
      'Cache-Control': 'no-store',
    });
    return res.end();
  }

  // Authenticated but MFA not yet verified → only /auth/* is allowed.
  if (!session.mfaVerified && !path.startsWith('/auth/')) {
    if (path.startsWith('/api/')) {
      res.writeHead(401, {
        'Content-Type': 'application/json',
        'Cache-Control': 'no-store',
      });
      return res.end(JSON.stringify({ error: 'MFA verification required' }));
    }
    res.writeHead(302, { Location: '/auth/totp', 'Cache-Control': 'no-store' });
    return res.end();
  }

  next();
}

function sendHtml(res, status, html) {
  res.writeHead(status, {
    'Content-Type': 'text/html; charset=utf-8',
    'Cache-Control': 'no-store',
    'X-Frame-Options': 'DENY',
    'X-Content-Type-Options': 'nosniff',
  });
  res.end(html);
}

/**
 * Vite plugin: install the full auth + RBAC middleware stack.
 * Add as the very first plugin so it wraps everything else.
 * @returns {import('vite').Plugin}
 */
export function authPlugin() {
  const install = (server) => {
    server.middlewares.use(authMiddleware);
    server.middlewares.use(requireAuthMiddleware);
    server.middlewares.use(authorizeMiddleware);
  };
  return {
    name: 'gev-auth',
    configureServer: install,
    configurePreviewServer: install,
  };
}

/**
 * Session management for God's Eye View.
 *
 * Sessions are server-side: a random token is stored in a signed, HttpOnly
 * cookie; the server holds the session record in memory with a TTL. Signing
 * uses HMAC-SHA-256 so a modified or forged cookie is rejected without a
 * database round-trip.
 *
 * Environment variables:
 *   GEV_SESSION_SECRET  – 32+ char secret used to sign tokens (required in
 *                          production; auto-generated for dev).
 *   GEV_SESSION_TTL_MS  – session lifetime in ms (default 8 h).
 * @module server/auth/session
 */
import { createHmac, randomBytes } from 'node:crypto';

const TTL_MS = Number(process.env.GEV_SESSION_TTL_MS) || 8 * 60 * 60 * 1000;
const COOKIE_NAME = 'gev_session';

/** Derive the signing secret once on startup. */
function resolveSecret() {
  const env = process.env.GEV_SESSION_SECRET;
  if (env && env.length >= 32) return env;
  if (process.env.NODE_ENV === 'production') {
    throw new Error(
      'GEV_SESSION_SECRET must be set to a 32+ character string in production.',
    );
  }
  // Dev-only fallback: a random secret that changes on every restart (forces
  // re-login after a server restart, which is acceptable for local dev).
  return randomBytes(32).toString('hex');
}

const SECRET = resolveSecret();

/** In-memory session store: token → { userId, roles, mfaVerified, expiresAt } */
const store = new Map();

/** Purge expired entries every 10 minutes. */
setInterval(
  () => {
    const now = Date.now();
    for (const [token, rec] of store) {
      if (rec.expiresAt <= now) store.delete(token);
    }
  },
  10 * 60 * 1000,
).unref();

/**
 * Create a new session and return the signed cookie value.
 * @param {{ userId: string, roles: string[], mfaVerified?: boolean }} opts
 */
export function createSession({ userId, roles, mfaVerified = false }) {
  const token = randomBytes(32).toString('hex');
  const expiresAt = Date.now() + TTL_MS;
  store.set(token, { userId, roles, mfaVerified, expiresAt });
  const sig = sign(token);
  return { cookieValue: `${token}.${sig}`, expiresAt };
}

/**
 * Resolve and validate a session from the Cookie header.
 * Returns the session record or null if absent/invalid/expired.
 * @param {import('http').IncomingMessage} req
 */
export function resolveSession(req) {
  const raw = parseCookie(req.headers?.cookie ?? '')[COOKIE_NAME];
  if (!raw) return null;
  const dot = raw.lastIndexOf('.');
  if (dot < 0) return null;
  const token = raw.slice(0, dot);
  const sig = raw.slice(dot + 1);
  if (!timingSafeEqual(sign(token), sig)) return null;
  const rec = store.get(token);
  if (!rec) return null;
  if (rec.expiresAt <= Date.now()) {
    store.delete(token);
    return null;
  }
  return { token, ...rec };
}

/**
 * Mark a session as MFA-verified.
 * @param {string} token
 */
export function markMfaVerified(token) {
  const rec = store.get(token);
  if (rec) rec.mfaVerified = true;
}

/**
 * Destroy a session (logout).
 * @param {string} token
 */
export function destroySession(token) {
  store.delete(token);
}

/**
 * Build the Set-Cookie header value for a new session.
 * @param {string} cookieValue
 * @param {number} expiresAt  – Unix ms
 */
export function buildSetCookie(cookieValue, expiresAt) {
  const expires = new Date(expiresAt).toUTCString();
  return (
    `${COOKIE_NAME}=${cookieValue}; ` +
    `Expires=${expires}; ` +
    `HttpOnly; ` +
    `SameSite=Strict; ` +
    `Path=/`
  );
}

/** Build the Set-Cookie header that clears the session cookie. */
export function buildClearCookie() {
  return (
    `${COOKIE_NAME}=; ` +
    `Expires=Thu, 01 Jan 1970 00:00:00 GMT; ` +
    `HttpOnly; ` +
    `SameSite=Strict; ` +
    `Path=/`
  );
}

// ── helpers ────────────────────────────────────────────────────────────────

function sign(token) {
  return createHmac('sha256', SECRET).update(token).digest('hex');
}

function timingSafeEqual(a, b) {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

function parseCookie(header) {
  const out = {};
  for (const part of header.split(';')) {
    const eq = part.indexOf('=');
    if (eq < 0) continue;
    const key = part.slice(0, eq).trim();
    out[key] = decodeURIComponent(part.slice(eq + 1).trim());
  }
  return out;
}

/**
 * Time-based One-Time Password (TOTP) implementation – RFC 6238 / RFC 4226.
 *
 * Used as the second factor in God's Eye View multi-factor authentication.
 * Compatible with standard authenticator apps (Google Authenticator, Aegis,
 * Authy, 1Password, etc.).
 *
 * Only Node built-ins are used (node:crypto); no external dependency.
 * @module server/auth/totp
 */
import { createHmac, randomBytes } from 'node:crypto';

const STEP = 30; // seconds per TOTP window
const DIGITS = 6;
const WINDOW = 1; // ±1 window tolerance for clock skew

/**
 * Generate a random Base32-encoded TOTP secret (160 bits / 32 chars).
 * @returns {string} Base32 secret
 */
export function generateTotpSecret() {
  return base32Encode(randomBytes(20));
}

/**
 * Compute the TOTP code for a secret at a given Unix timestamp (seconds).
 * @param {string} secret  – Base32-encoded TOTP secret
 * @param {number} [ts]    – Unix time in seconds (default: now)
 * @returns {string} Zero-padded 6-digit code
 */
export function computeTotp(secret, ts = Math.floor(Date.now() / 1000)) {
  const counter = Math.floor(ts / STEP);
  return hotp(base32Decode(secret), counter);
}

/**
 * Verify a user-supplied TOTP code against a secret.
 * Accepts codes from one window before and after the current window to
 * tolerate clock skew.
 *
 * @param {string} secret  – Base32-encoded TOTP secret
 * @param {string} code    – 6-digit code supplied by the user
 * @param {number} [ts]    – Unix time in seconds (default: now)
 * @returns {boolean}
 */
export function verifyTotp(secret, code, ts = Math.floor(Date.now() / 1000)) {
  if (!/^\d{6}$/.test(code)) return false;
  const key = base32Decode(secret);
  const counter = Math.floor(ts / STEP);
  for (let delta = -WINDOW; delta <= WINDOW; delta++) {
    if (hotp(key, counter + delta) === code) return true;
  }
  return false;
}

/**
 * Build an otpauth:// URI suitable for QR-code generation.
 * @param {string} secret    – Base32 secret
 * @param {string} issuer    – Application name shown in the authenticator
 * @param {string} account   – User identifier (e.g. email)
 * @returns {string}
 */
export function totpUri(secret, issuer, account) {
  const params = new URLSearchParams({
    secret,
    issuer,
    algorithm: 'SHA1',
    digits: String(DIGITS),
    period: String(STEP),
  });
  const label = encodeURIComponent(`${issuer}:${account}`);
  return `otpauth://totp/${label}?${params}`;
}

// ── HOTP (RFC 4226) ─────────────────────────────────────────────────────────

function hotp(key, counter) {
  const buf = Buffer.alloc(8);
  // Write 64-bit big-endian counter (JS bitwise ops are 32-bit, use division)
  const hi = Math.floor(counter / 0x100000000);
  const lo = counter >>> 0;
  buf.writeUInt32BE(hi, 0);
  buf.writeUInt32BE(lo, 4);

  const mac = createHmac('sha1', key).update(buf).digest();
  const offset = mac[mac.length - 1] & 0x0f;
  const code =
    ((mac[offset] & 0x7f) << 24) |
    ((mac[offset + 1] & 0xff) << 16) |
    ((mac[offset + 2] & 0xff) << 8) |
    (mac[offset + 3] & 0xff);
  return String(code % 10 ** DIGITS).padStart(DIGITS, '0');
}

// ── Base32 (RFC 4648, no padding required for decode) ───────────────────────

const B32_CHARS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';

function base32Encode(buf) {
  let bits = 0;
  let value = 0;
  let out = '';
  for (const byte of buf) {
    value = (value << 8) | byte;
    bits += 8;
    while (bits >= 5) {
      out += B32_CHARS[(value >>> (bits - 5)) & 0x1f];
      bits -= 5;
    }
  }
  if (bits > 0) out += B32_CHARS[(value << (5 - bits)) & 0x1f];
  return out;
}

function base32Decode(str) {
  const s = str.toUpperCase().replace(/=+$/, '');
  let bits = 0;
  let value = 0;
  const out = [];
  for (const ch of s) {
    const idx = B32_CHARS.indexOf(ch);
    if (idx < 0) continue;
    value = (value << 5) | idx;
    bits += 5;
    if (bits >= 8) {
      out.push((value >>> (bits - 8)) & 0xff);
      bits -= 8;
    }
  }
  return Buffer.from(out);
}
